import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as r,o as i,c as o,a3 as a}from"./chunks/framework.g9mfNVRQ.js";const h=JSON.parse('{"title":"Libre NFC","description":"","frontmatter":{"source_hash":"9c60a43392","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/install/libreNFC.md","filePath":"it/install/libreNFC.md"}'),s={name:"it/install/libreNFC.md"};function n(l,e,p,c,d,u){return i(),o("div",null,[...e[0]||(e[0]=[a('<p>Oggi quasi tutti i telefoni supportano la scansione NFC. Se il tuo la supporta, puoi scansionare il tuo sensore Libre 1, 14 giorni USA, Libre 2/2+ (UE) e Libre Pro con xDrip oltre che con LibreLink, l&#39;app del produttore. Nota che la scansione NFC di xDrip <strong>non può</strong> avviare un sensore: solo LibreLink (o il lettore) può farlo.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   LibreAlarm</p></div><h2 id="supported-data-sources" tabindex="-1">Sorgenti dati supportate <a class="header-anchor" href="#supported-data-sources" aria-label="Permalink to &quot;Sorgenti dati supportate {#supported-data-sources}&quot;">​</a></h2><p>Per accedere al menu NFC devi selezionare una delle sorgenti dati Libre.</p><p>Se userai xDrip solo per scansionare il sensore, scegli LibreAlarm.</p><div class="info custom-block"><p class="custom-block-title">Nota</p><p>Se attivi il supporto alla scansione NFC di xDrip, disattiva qualsiasi altra app che tenti di leggere dispositivi NFC, per evitare conflitti. Questo vale soprattutto per l&#39;app Libre del produttore.</p></div><h4 id="configure-nfc" tabindex="-1">Configurare NFC <a class="header-anchor" href="#configure-nfc" aria-label="Permalink to &quot;Configurare NFC {#configure-nfc}&quot;">​</a></h4><p>Configura NFC esattamente <a href="./../use/NFC.html">così</a>.</p><h2 id="supported-sensors" tabindex="-1">Sensori supportati <a class="header-anchor" href="#supported-sensors" aria-label="Permalink to &quot;Sensori supportati {#supported-sensors}&quot;">​</a></h2><p>Solo Libre 1 e Pro sono supportati nativamente da xDrip per le letture NFC. Per scansionare un Libre 14 giorni USA o un Libre 2 europeo, devi installare sul telefono un <a href="./../use/OOP.html">algoritmo OOP (Out of Process Algorithm)</a>.</p><table tabindex="0"><thead><tr><th style="text-align:center;">- Libre 1 / Pro -</th><th style="text-align:center;">- 14 giorni USA -</th><th style="text-align:center;">- Libre 2/2+ UE -</th></tr></thead><tbody><tr><td style="text-align:center;"><code>Sì</code></td><td style="text-align:center;"><code>OOP2</code></td><td style="text-align:center;"><code>OOP2</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Intervallo minimo di scansione</p><p>Attendi almeno 60 secondi tra due scansioni NFC.</p></div><br><p>Prosegui con <a href="./../use/startsensor.html#libre">Inizializza Sensore</a>, ricordando che dovrai scansionare il sensore per ottenere le prime letture.</p><br><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Ultima modifica 6/12/2024</em></a></p>',17)])])}const g=r(s,[["render",n]]);export{h as __pageData,g as default};
